export const createScene = async function (engine, canvas, BABYLON) {
  const scene = new BABYLON.Scene(engine);
  scene.clearColor = new BABYLON.Color4(0, 0, 0, 1);

  const isMobile = navigator.userAgentData ? navigator.userAgentData.mobile : /Android|iPhone|iPad|iPod/i.test(navigator.userAgent);
  const isARSupported = await BABYLON.WebXRSessionManager.IsSessionSupportedAsync("immersive-ar");

  const advancedTexture = BABYLON.GUI.AdvancedDynamicTexture.CreateFullscreenUI("UI");
  const mainContainer = new BABYLON.GUI.StackPanel();
  mainContainer.verticalAlignment = BABYLON.GUI.Control.VERTICAL_ALIGNMENT_CENTER;
  advancedTexture.addControl(mainContainer);

  // 기본 환경 설정 (Ground와 Skybox는 생성하지 않음)
  scene.createDefaultEnvironment({ createGround: false, createSkybox: false });

  // 이미지 트래킹 모듈에 의해 변환될 루트 노드 생성
  const root = new BABYLON.TransformNode("root", scene);
  root.setEnabled(false);

  // glTF 모델 로드
  const [model1Result, model2Result] = await Promise.all([
    BABYLON.SceneLoader.ImportMeshAsync("", "https://raw.githubusercontent.com/UN1TOne/3DAsset/master/", "slice pizza.glb", scene),
    BABYLON.SceneLoader.ImportMeshAsync("", "https://raw.githubusercontent.com/UN1TOne/3DAsset/master/", "batman in gotham ai.glb", scene),
  ]);

  const root1 = new BABYLON.TransformNode("root1", scene);
  model1Result.meshes[0].parent = root1;
  root1.setEnabled(false);
  model1Result.meshes[0].scaling.scaleInPlace(0.25);
  model1Result.meshes[0].rotate(BABYLON.Axis.Y, -Math.PI / 3, BABYLON.Space.LOCAL);

  const root2 = new BABYLON.TransformNode("root2", scene);
  model2Result.meshes[0].parent = root2;
  root2.setEnabled(false);
  model2Result.meshes[0].scaling.scaleInPlace(0.025);
  model1Result.meshes[0].rotate(BABYLON.Axis.Y, Math.PI, BABYLON.Space.LOCAL);

  const roots = [root1, root2];

  // XR 경험 도우미(Experience Helper) 초기화
  const xr = await scene.createDefaultXRExperienceAsync({
    uiOptions: { sessionMode: "immersive-ar" },
  });

  const imageTracking = xr.baseExperience.featuresManager.enableFeature(BABYLON.WebXRFeatureName.IMAGE_TRACKING, "latest", {
    images: [
      { src: "https://raw.githubusercontent.com/UN1TOne/3DAsset/master/Images/pizza.png", estimatedRealWorldWidth: 0.2 },
      { src: "https://raw.githubusercontent.com/UN1TOne/3DAsset/master/Images/batman marker.png", estimatedRealWorldWidth: 0.2 },
    ],
  });

  // 이미지가 트래킹되어 위치가 업데이트될 때마다 실행되는 콜백
  imageTracking.onTrackedImageAddedObservable.add((image) => {
    console.log("Marker Found:", image.originalImageIndex);
    const target = roots[image.originalImageIndex];
    if (target) {
      target.setEnabled(true);
      image.transformationMatrix.decompose(target.scaling, target.rotationQuaternion, target.position);
    }
  });

  // 마커 위치 업데이트
  imageTracking.onTrackedImageUpdatedObservable.add((image) => {
    const target = roots[image.originalImageIndex];
    if (target) {
      target.setPreTransformMatrix(image.transformationMatrix);
    }
  });

  if (isARSupported) {
    const mobileText = new BABYLON.GUI.TextBlock();
    mobileText.text = "1. Tap XR button (bottom right)\n2. Scan the marker on your PC screen";
    mobileText.color = "white";
    mobileText.fontSize = 20;
    mobileText.height = "80px";
    mainContainer.addControl(mobileText);

    // XR 세션 상태 변화를 감시하여 버튼 클릭 시 GUI 숨김
    xr.baseExperience.onStateChangedObservable.add((state) => {
      if (state === BABYLON.WebXRState.IN_XR) {
        // XR 모드에 진입했을 때 (버튼 클릭 직후)
        mainContainer.isVisible = false;
      } else if (state === BABYLON.WebXRState.NOT_IN_XR) {
        mainContainer.isVisible = true;
      }
    });
  } else if (!isMobile) {
    const pcText = new BABYLON.GUI.TextBlock();
    pcText.text = "Scan this image with your smartphone AR";
    pcText.color = "cyan";
    pcText.fontSize = 24;
    pcText.height = "50px";
    mainContainer.addControl(pcText);

    const markerImg = new BABYLON.GUI.Image("marker", "https://raw.githubusercontent.com/UN1TOne/3DAsset/master/Images/pizza.png");
    markerImg.width = "300px";
    markerImg.height = "300px";
    mainContainer.addControl(markerImg);

    const subText = new BABYLON.GUI.TextBlock();
    subText.text = "It's PIZZA TIME!";
    subText.color = "white";
    subText.fontSize = 18;
    subText.height = "40px";
    mainContainer.addControl(subText);
  }

  return scene;
};
